// Min-heap idea (array)
// parent(i) = (i-1)>>1
// left(i)   = 2i+1
// right(i)  = 2i+2
function push(h, x){
  h.push(x);
  let i = h.length-1;
  while(i>0){
    const p=(i-1)>>1;
    if(h[p]<=h[i]) break;
    [h[p],h[i]]=[h[i],h[p]]; i=p;
  }
}

