// Dictionary: ['cat', 'car', 'care', 'dog']
// Stored as a Trie:

//        root
//       /    \
//      c      d
//      |      |
//      a      o
//     / \     |
//    t*  r    g*
//        |
//        e*
//
// (* marks end of a word)
//
// Type 'ca' → walk root→c→a → all words below = matches!
// 'cat', 'car', 'care' instantly available.

class Trie {
  constructor() { this.root = {}; }

  insert(word) {
    let node = this.root;
    for (const ch of word) {
      node[ch] ||= {};         // create branch if missing
      node = node[ch];
    }
    node.isEnd = true;          // mark word ending
  }

  search(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node[ch]) return false; // path doesn't exist
      node = node[ch];
    }
    return !!node.isEnd;        // must be marked as a word
  }
}

// Autocomplete 'ca' from trie of [cat, car, care, dog]:

// 1. Walk to 'ca' node:
let node = root.c.a;

// 2. DFS down, collecting every isEnd:
function collect(node, prefix, results) {
  if (node.isEnd) results.push(prefix);
  for (const ch in node) {
    if (ch !== 'isEnd') collect(node[ch], prefix + ch, results);
  }
}
const results = [];
collect(node, 'ca', results);
// results = ['cat', 'car', 'care'] ✓

