//   A → B → D → E → C → F  (full path then back up)

// BFS uses a QUEUE (FIFO): take the oldest one next.
// DFS uses a STACK or RECURSION: take the newest one next.

function bfs(start, target, graph) {
  const queue = [[start, 0]];   // [node, distance]
  const seen = new Set([start]);
  while (queue.length) {
    const [node, dist] = queue.shift();
    if (node === target) return dist;     // found!
    for (const next of graph[node]) {
      if (!seen.has(next)) {
        seen.add(next);                    // mark on ENQUEUE
        queue.push([next, dist + 1]);
