// Jump Game (greedy CORRECT): can we reach last index?
// nums = [2,3,1,1,4]
function canJump(nums) {
  let reach = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > reach) return false;            // unreachable
    reach = Math.max(reach, i + nums[i]);    // greedy: max reach
  }
  return true;
}
// Exchange argument: extending reach NEVER hurts —
// you can always choose to stop short later. ∴ greedy is safe.

