class DSU {
  constructor(n) {
    this.parent = [...Array(n).keys()];
    this.rank = Array(n).fill(0);
  }
  find(x) {
    if (this.parent[x] !== x)
      this.parent[x] = this.find(this.parent[x]); // compress!
    return this.parent[x];
  }
  union(a, b) {
    let ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;      // already connected
    if (this.rank[ra] < this.rank[rb]) [ra, rb] = [rb, ra];
    this.parent[rb] = ra;             // shorter under taller
    if (this.rank[ra] === this.rank[rb]) this.rank[ra]++;
    return true;                       // merged two groups
  }
}

// Count connected components from edge list:
function countComponents(n, edges) {
  const dsu = new DSU(n);
  let components = n;              // everyone separate
  for (const [a, b] of edges)
    if (dsu.union(a, b)) components--;  // real merge
  return components;
}

// Find the edge that creates a cycle:
for (const [a, b] of edges)
  if (!dsu.union(a, b)) return [a, b]; // already connected!

// vs BFS/DFS: DSU shines when edges ARRIVE OVER TIME —
// no need to rebuild or re-traverse the graph per query.

